import json
d=json.load(open('SUCCESSOR-RESULT.json',encoding='utf-8'))
print(list(d.keys()))
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,p+'.'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o[:5]): walk(v,p+f'[{i}]')
    else:
        s=str(o)
        if 'plan' in p.lower() or 'criteri' in p.lower(): print(p,':',s[:160])
walk(d)
" | head -120

