1	import { stateAfter } from '/src/queue.ts';
2	import { statusVisuals, statusCell, compactStatus, display, motionQuery, statusFrame } from '/src/queue-view-successor.ts';
3	
4	const motion = matchMedia(motionQuery);
5	const preferenceChanges = [];
6	let observedReduced = motion.matches;
7	const panel = display.background;
8	document.documentElement.style.setProperty('--panel', panel);
9	const cache = new Map();
10	const cells = [];
11	const consumers = { statusCell, compactStatus };
12	const events = ['idle', 'started', 'pause', 'ok', 'error'].filter(event => event === 'idle' || statusVisuals[stateAfter(event)]);
13	document.querySelectorAll('[data-event]').forEach(button => { button.hidden = !events.includes(button.dataset.event); });
14	const errors = [];
15	window.addEventListener('error', event => errors.push(event.message));
16	window.addEventListener('unhandledrejection', event => errors.push(String(event.reason)));
17	const digest = async bytes => [...new Uint8Array(await crypto.subtle.digest('SHA-256', bytes))].map(x => x.toString(16).padStart(2, '0')).join('');
18	
19	async function imageFor(path) {
20	  if (!cache.has(path)) cache.set(path, (async () => {
21	    const response = await fetch(`/${path}`);
22	    if (!response.ok) return { available: false, status: response.status, path };
23	    const data = await response.arrayBuffer();
24	    const image = new Image();
25	    const url = URL.createObjectURL(new Blob([data], { type: response.headers.get('Content-Type') }));
26	    try { image.src = url; await image.decode(); }
27	    finally { URL.revokeObjectURL(url); }
28	    return { available: true, image, path, sha256: await digest(data), width: image.naturalWidth, height: image.naturalHeight };
29	  })());
30	  return cache.get(path);
31	}
32	
33	function paint(canvas, asset, frames, scale, elapsed, state) {
34	  const [width, height] = display.cell;
35	  const frame = statusFrame(state, elapsed, motion.matches);
36	  const context = canvas.getContext('2d', { willReadFrequently: true });
37	  context.imageSmoothingEnabled = display.filter !== 'nearest';
38	  context.fillStyle = panel;
39	  context.fillRect(0, 0, canvas.width, canvas.height);
