from PIL import Image
import hashlib
def comps(px,w,h,x0):
    seen=set(); n=0; boxes=[]
    for y in range(h):
        for x in range(x0,x0+16):
            if px[x,y][3]>0 and (x,y) not in seen:
                n+=1; st=[(x,y)]; seen.add((x,y)); xs=[];ys=[]
                while st:
                    cx,cy=st.pop(); xs.append(cx); ys.append(cy)
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=cx+dx,cy+dy
                        if x0<=nx<x0+16 and 0<=ny<h and (nx,ny) not in seen and px[nx,ny][3]>0:
                            seen.add((nx,ny)); st.append((nx,ny))
                boxes.append([min(xs)-x0,min(ys),max(xs)-x0+1,max(ys)+1])
    return n,boxes
for p in ['renderer-successor/assets/working.png','renderer-successor/assets/ready-confirmed.png','renderer-successor/assets/error-retry.png','renderer-successor/assets/paused.png']:
    im=Image.open(p).convert('RGBA'); w,h=im.size; px=im.load()
    print('==',p,w,h, hashlib.sha256(open(p,'rb').read()).hexdigest()[:16])
    for cell in range(w//16):
        x0=cell*16
        alphas={}
        colors=set()
        for y in range(h):
            for x in range(x0,x0+16):
                a=px[x,y][3]; alphas[a]=alphas.get(a,0)+1
                if a>0: colors.add(px[x,y][:3])
        n,boxes=comps(px,w,h,x0)
        edge_touch=[b for b in boxes if b[0]==0 and b[1]==0 and b[2]==16 and b[3]==16]
        print(f'  cell {cell}: alpha hist {dict(sorted(alphas.items()))} components {n} boxes {boxes} colors {len(colors)} fullspan {len(edge_touch)}')
        print('   sample colors:', sorted(colors)[:6])
"

